window.MONSTER_CHUNK_39 = [{"name":"Thognorok","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["aquatic","chaotic","evil","extraplanar","qlippoth"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":9,"ac_flat_footed":16,"ac_mods":"-1 Dex, +7 natural","hp":37,"hd":"5d10+10","hdvalue":5,"fort":6,"ref":0,"will":2,"defensive_abilities":["all-around vision amorphous"],"dr":"5/cold iron or lawful","immunities":["cold","mind-affecting effects","poison"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":15,"speed":[{"type":"land","speed":20},{"type":"swim","speed":30}],"melee":"3 bites +7 (1d6+1 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"acid web","details":"+4 ranged, DC 16, 5 hp"},{"type":"horrific appearance"},{"type":"poison"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"excruciating deformation"}]},{"frequency":"3/day","spells":[{"spell":"acid arrow"},{"spell":"protection from law"},{"spell":"vomit swarm"}]}],"strength":13,"dexterity":8,"constitution":15,"intelligence":8,"wisdom":13,"charisma":12,"baseatk":5,"cmb":4,"cmd":15,"cmd_special":"can't be tripped","feats":[{"feat":"Ability Focus (acid web)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Climb","value":9},{"skill":"Intimidate","value":9},{"skill":"Knowledge (planes)","value":7},{"skill":"Perception","value":9},{"skill":"Stealth","value":10},{"skill":"Swim","value":9}],"languages":["Abyssal","telepathy 100 ft."],"sq":[{"type":"amphibious"},{"type":"compression"}],"environments":["any (Abyss)"],"organizations":["solitary","pair","gang (3-5)"],"treasure":"none","description_visual":"This obscene mass looks like a melted blob crossed with a spider, ceaselessly lashing out with its hairy, wriggling legs.","group":"Qlippoth","source":"Inner Sea Gods","special_abilities":[{"type":"Acid Web","kind":"Su","details":"This ability functions like the web universal monster ability, except a creature entangled by a thognorok's web also takes 1 point of acid damage each round."},{"type":"Horrific Appearance","kind":"Su","details":"Any creature that witnesses a thognorok's horrific appearance could find itself overwhelmed with revulsion at the qlippoth's constantly sprouting and waving insectile legs, becoming sickened for 1d6 rounds (Will DC 13 negates). The save DC is Charisma-based."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 14; frequency 1/round for 4 rounds; effect 1d2 Str; cure 2 consecutive saves."}],"description":"Although thognoroks are considered servitor qlippoth of Rovagug, they are actually sentient symbiotes that once had the misfortune of dining on the Rough Beast's skin, blood, and other fluids. Equally at home on solid ground or swimming through toxic liquids, a thognorok hunts and consumes foreign materials and creatures that would impede its endless hunger to feed on more divine flesh-whether Rovagug's or another deity's.\n\nBecause of its tainted connection with the god of destruction, a thognorok obeys any telepathic or chemical command transmitted to it by the god-whether it be a direct command, or even the orders of a powerful priest of the foul god. Thognoroks are rarely directly controlled by Rovagug; instead, they're left to their own destructive rampages. The exception to this is when they accumulate in vast numbers near planar scars and rifts on the Material Plane where the god left some fleck of his terrible carapace or dripped vile and blasphemous liquid from his wounds.\n\nIn such instances, the thognoroks try to fulfil whatever whim possessed the deity at the moment of his ages-old passing, typically the destruction of some site of celestial power or other random act of devastation.\n\nA common thognorok measures about 5 ft. tall and weighs over 200 pounds.","ecology":"","habitat_society":""},{"name":"Thriae Soldier","cr":4,"xp":1200,"alignment":"LN","size":"Medium","type":"monstrous humanoid","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+4 armor, +3 Dex, +0 natural","hp":42,"hd":"5d10+15","hdvalue":5,"fort":4,"ref":7,"will":2,"immunities":["poison","sonic"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"sting +10 (1d8+7 plus poison)","ranged":"composite longbow +8 (1d8+5/x3 plus poison) or   Rapid Shot +6 (1d8+5/x3 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"merope consumption"}],"strength":20,"dexterity":17,"constitution":16,"intelligence":12,"wisdom":13,"charisma":15,"baseatk":5,"cmb":-2,"cmd":3,"feats":[{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"}],"skills":[{"skill":"Fly","value":13},{"skill":"Intimidate","value":10},{"skill":"Perception","value":9},{"skill":"Stealth","value":9},{"skill":"Survival","value":9}],"languages":["Common","Sylvan"],"environments":["any"],"organizations":["pair","troop (3-8)","company (9-20 soldiers, 2-4 rangers of 3-5th level, 1-2 rogues of 4-6th level, and 1 fighter commander of 5-8th level)"],"treasure":"standard (chain shirt, composite longbow [+5 Str] with 20 arrows, 1 dose of merope)","description_visual":"This creature has the upper body of a woman and the lower body of a bee. She wields a longbow with uncanny skill.","group":"Thriae","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Merope Consumption","kind":"Su","details":"Once per day as a standard action, a thriae soldier can consume a dose of merope in order to enhance her combat abilities for 1d6+3 rounds. Starting on the round after the merope is consumed, the thriae soldier gains a +2 insight bonus on attack rolls and saving throws, and gains fast healing 3."},{"type":"Poison","kind":"Ex","details":"Sting or arrow-injury; save Fort DC 15; frequency 1/round for 6 rounds; effect 1d2 Str; cure 1 save. As a free action, a thriae soldier can apply her venom to an arrow as she fires the shot. The save DC is Constitution-based."}],"description":"The guardians of the thriae colony and its treasures, thriae soldiers make up the backbone of a hive's defenses. Whether patrolling the perimeter of the hive or protecting its queen and seers from attackers, soldiers are a crucial asset ensuring a colony's survival, and so it makes sense that they compose the majority of thriae populations. While not as spiritually powerful as their seer and queen kin, soldiers possess remarkable agility and skill with the bow. Guards remain stationed in pairs outside doors to important areas, such as the meditation chambers of seers and the enormous private quarters of the queen, and when their duties take them outside the walls of the hive, they travel in large convoys.\n\nA thriae soldier's stinger carries within it especially potent venom similar to that of giant bees, and the soldier can easily apply this poison to her weapons. While most soldiers carry bows, they are also trained at an early age with a multitude of both melee and ranged weapons, and some prefer the feel of a sword or hammer. Regardless of the type, all thriae weapons and armors are expertly crafted, made of steel and gilded with intricate decorations of gold and amber-hued gems. Thriae soldiers are often talented artisans as well as warriors, and most create their own weapons to bear in combat.\n\nSince there are exponentially more soldiers than seers in any given colony, thriae queens ration merope sparingly to soldiers, whose use of it doesn't provoke the divine insight cherished by thriae culture, but rather inspires courage and brute strength on the battlefield. When a thriae soldier consumes merope, her reflexes quicken, her wits sharpen, and she gains a second wind, so most individuals save their rationed doses for times of dire need. When circumstances are especially grim, commanders of thriae militias will order all of their troops to consume their merope at once, giving the company the final burst of strength it needs to turn the tide of battle.\n\nThriae soldiers are heavier-set than most of their slender thriae sisters, and average individuals weigh about 200 pounds and measure 6 ft. from head to toe.","ecology":"","habitat_society":""},{"name":"Thyrlien","cr":4,"xp":1200,"alignment":"CG","size":"Small","type":"outsider","subtypes":["azata","chaotic","extraplanar","good","shapechanger"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect evil"},{"type":"detect magic"},{"type":"low-light vision"}],"ac":16,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+2 Dex, +3 natural, +1 size","hp":39,"hd":"6d10+6","hdvalue":6,"hp_mods":["fast healing 1"],"fort":3,"ref":7,"will":4,"save_mods":"+4 vs. poison","dr":"5/evil","immunities":["electricity","petrification"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"sr":15,"speed":[{"type":"land","speed":20},{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"bite +9 (1d3-1 plus poison), 2 wings +4 (1d4-1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"evil outsiders +2, vermin +2"},{"type":"poison"},{"type":"starlight blast"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"detect magic"}]},{"frequency":"1/day","spells":[{"spell":"blindness/deafness"},{"spell":"neutralize poison"},{"spell":"true strike"}]},{"frequency":"3/day","spells":[{"spell":"cure light wounds"},{"spell":"locate creature"},{"spell":"magic missile"},{"spell":"message"}]}],"strength":9,"dexterity":15,"constitution":12,"intelligence":12,"wisdom":15,"charisma":14,"baseatk":6,"cmb":23,"cmd":33,"feats":[{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Fly","value":8},{"skill":"Knowledge (planes)","value":10},{"skill":"Knowledge (religion)","value":10},{"skill":"Perception","value":11},{"skill":"Perform (any one)","value":11},{"skill":"Stealth","value":15},{"skill":"Survival","value":11}],"languages":["Celestial","Draconic","Infernal","truespeech"],"sq":[{"type":"change shape","details":"giant moth [use giant wasp stats]; vermin shape"}],"environments":["any (Elysium)"],"organizations":["solitary","pair","squad (3-5)"],"treasure":"standard","description_visual":"This fey-looking humanoid is colored in shades of gray. Its wings are decorated with colored motes resembling a starry night sky.","group":"Azata","source":"Inner Sea Gods","special_abilities":[{"type":"Fast Healing","kind":"Ex","details":"A thyrlien has fast healing 1 only when outside under a night sky (whether the sky is cloudy or clear)."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 14; frequency 1/round for 6 rounds; effect 1d3 Str; cure 2 consecutive saves."},{"type":"Starlight Blast","kind":"Su","details":"As a standard action once every 1d4 rounds, a thyrlien can tap into Desna's divine radiance and unleash a blast of holy twilight in a 5-foot burst. All creatures in this area take 2d4 points of holy damage, plus 1 point for each step their alignment deviates from chaotic good. For example, a chaotic neutral or neutral good creature would take 2d4+1 points of damage, a neutral creature would take 2d4+2 points of damage, and a lawful evil creature would take 2d4+4 points of damage. A DC 14 Reflex save negates this damage. Chaotic good creatures are unaffected by this ability. The save DC is Constitution-based."}],"description":"A thyrlien is a unique type of azata created by Desna.\n\nIntended as rare warrior counterparts to lyrakien, thyrlien are tasked with watching over nighttime travelers. Specifically hunting the servants of Lamashtu and Ghlaunder, thyrlien wander lonely roads and dark alleys, hoping to confront or counter the dark things that so often hunt such ominous spots. Superficially humanoid, a thyrlien's attacks reveal its nonhuman origins. Venomous saliva coats mouth and its delicate-looking wings are actually as stiff as wood and have razor sharp edges. A thyrlien is skilled at tracking using conventional and magical methods and is savvy to the ways of its chosen prey. These servants of the goddess of luck stand about 2 ft. tall and weigh around 15 pounds.","ecology":"","habitat_society":""},{"name":"Tiger","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"animal","init":6,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+2 Dex, +3 natural, -1 size","hp":45,"hd":"6d8+18","hdvalue":6,"fort":8,"ref":7,"will":2,"speed":[{"type":"land","speed":40}],"melee":"2 claws +10 (1d8+6 plus grab), bite +9 (2d6+6 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws +10, 1d8+6"}],"strength":23,"dexterity":15,"constitution":17,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":4,"cmb":4,"cmb_special":"+4 vs. grapple","cmd":16,"feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Perception","value":8},{"skill":"Stealth","value":7,"special":"+11 in areas of tall grass"},{"skill":"Swim","value":11}],"environments":["any forests"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This powerful feline predator moves with a deadly grace, its reddish-orange fur slashed with black stripes.","source":"PFRPG Bestiary","description":"Tigers stand more than 3 ft. tall at the shoulder and are about 9 ft. long. They weigh from 400 to 600 pounds.\n\nTigers are usually the top animal predators in their territories, and have been known to kill bears, crocodiles, giant snakes, wolves, and even other great cats. Even humanoids are far from safe, especially in cases where a tiger has developed a taste for humanoid flesh. Tigers prefer terrain with plenty of cover and proximity to water as their hunting grounds.\n\nWhile the tiger itself is a fearsome predator, its strength and ferocity pales in comparison to that of the larger dire tiger.\n\nKnown to many scholars as the smilodon and to tribal societies as the saber-toothed tiger, the dire tiger is invariably one of the region's top predators. Its defining feature is a pair of huge incisors that hang down like fearsome knives from the upper jaw, protruding menacingly even when the creature's mouth is shut.\n\nThese immense hunting cats grow to be over 12 ft. long and can weigh up to 6,000 pounds.","ecology":"","habitat_society":""},{"name":"Troggle","cr":4,"xp":1200,"alignment":"CE","size":"Large","type":"humanoid","subtypes":["giant"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+1 Dex, +5 natural, -1 size","hp":32,"hd":"5d8+10","hdvalue":5,"hp_mods":["regeneration 5 (acid or fire)"],"fort":6,"ref":2,"will":0,"speed":[{"type":"land","speed":40}],"melee":"bite +7 (1d6+5 plus trip), 2 claws +7 (1d4+5)","space":"10 ft.","reach":"10 ft.","strength":20,"dexterity":13,"constitution":14,"intelligence":5,"wisdom":10,"charisma":5,"baseatk":3,"cmb":2,"cmd":11,"feats":[{"feat":"Combat Reflexes"},{"feat":"Iron Will"},{"feat":"Night Stalker"},{"feat":"Skill Focus (Stealth)","type":"bonus"}],"skills":[{"skill":"Climb","value":9},{"skill":"Perception","value":6},{"skill":"Stealth","value":1,"special":"+5 in dim light or darkness"}],"languages":["Giant"],"sq":[{"type":"ogre blood"}],"environments":["cold hills","cold mountains"],"organizations":["solitary","pair","gang (3-4)"],"treasure":"half","description_visual":"This leathery creature has a lanky, ogre-like shape, but walks on all fours. Its claws, teeth, tail, and gait give it a degenerate , bestial appearance.","source":"Monster Codex","special_abilities":[{"type":"Ogre Blood","kind":"Ex","details":"Troggles count as ogres for the purpose of any effects related to race."}],"description":"These dim-witted creatures are a mongrel cross between a troll and an ogre, combining the worst features of each. They usually act like animals and move on all fours, but can rear up on their hind legs to attack with their sharp claws and vicious bites. Some ogres keep them as pets, treating them as exceptionally stupid but hilarious kinfolk. Trolls usually kill troggles on sight, and have been known to band together to wipe out entire ogre clans that possess troggles.","ecology":"","habitat_society":""},{"name":"Tuyewera","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"undead","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+3 Dex, +3 natural","hp":39,"hd":"6d8+12","hdvalue":6,"fort":4,"ref":5,"will":6,"defensive_abilities":["daylight invisibility"],"dr":"5/magic","immunities":["undead traits"],"weaknesses":["vulnerable to sunlight"],"speed":[{"type":"land","speed":20}],"melee":"slam +7 (1d6+4), tongue +8 (1d4+4 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"1d4+4"},{"type":"lure"},{"type":"steal tongue"},{"type":"suffocation"}],"strength":17,"dexterity":16,"intelligence":8,"wisdom":13,"charisma":15,"baseatk":4,"cmb":7,"cmd":20,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Weapon Focus (tongue)"}],"skills":[{"skill":"Bluff","value":8},{"skill":"Perception","value":10},{"skill":"Stealth","value":12}],"languages":["Common (but see steal tongue below)"],"environments":["any"],"organizations":["solitary"],"treasure":"standard","description_visual":"The figure that crawls up from the grave may have once been a living man, but it is now wholly a monster. Its flesh crawls with worms and seeps with decay, allowing bones and internal organs to slip through hideous tears here and there. Its jaw distends and a long tongue whips out, almost like a tentacle. Its legs have been severed at the knee, forcing it to scrabble forward on all fours like some deranged beast.","source":"AP 37","special_abilities":[{"type":"Daytime Invisibility","kind":"Su","details":"During the day, a tuyewera is invisible as long as it doesn't attack. This effect functions as the invisibility spell, but lasts for the entire day. If a tuyewera takes any action that would negate its invisibility (such as attacking), it remains visible until it takes a full-round action to reactivate its invisibility."},{"type":"Lure","kind":"Su","details":"If a tuyewera possesses a stolen tongue (see steal tongue ability), it can lure creatures into a trancelike state and compel them to approach as a standard action. When a tuyewera uses its lure, it must target an intelligent creature within 120 ft. to which it has line of effect (but not necessarily line of sight). The tuyewera must concentrate to maintain the lure's effects. It then calls out to the creature, beckoning it to approach. The target can resist this lure by making a successful DC 15 Will save, after which that target is immune to that tuyewera's lure ability until the tuyewera gains a different tongue. If the tuyewera uses the target's name during the lure, the target suffers a -2 penalty on the Will save. If the target fails, she becomes fascinated and attempts to approach the tuyewera by the shortest, safest route possible. Once the target is adjacent to the tuyewera, she remains motionless and offers no resistance to the undead's attacks (although once the tuyewera attacks, it ceases concentration and the victim is free to act, assuming she survives the monster's attack). This is a sonic mindaffecting charm effect. The save DC is Charisma-based."},{"type":"Suffocation","kind":"Su","details":"A tuyewera doesn't breathe itself, but it can attempt to steal the breath of a helpless, fascinated, or stunned adjacent creature as a standard action. When the tuyewera attempts this, it moves its mouth next to the victim's mouth and inhales, drawing the victim's breath out of her body. The victim can attempt to resist this attack by making a DC 15 Fortitude save. If she fails, the victim is stunned for 1 round and begins to suffocate. The victim falls unconscious on the second round, drops to -1 hit points on the third, and dies of suffocation on the fourth. Each round, the victim may attempt a new DC 15 Fortitude save to end the suffocation effect. The save DC is Charisma-based."},{"type":"Steal Tongue","kind":"Su","details":"A tuyewera doesn't possess a tongue of its own when it is created-it must steal a tongue from a recently slain (no more than 1 day ago) creature before it can speak, attack with its tongue, or use its lure or constriction attacks. Stealing a tongue is a full-round action, after which the stolen tongue merges with the tuyewera's jaw. The tuyewera gains the ability to speak and understand all of the languages known by the dead body from which the tongue was harvested, and its voice sounds exactly like that of the dead creature while it still lived. The monster's new tongue is a dangerous weapon as well, and can extend to a length of nearly 5 ft. to attack and constrict foes. A stolen tongue only lasts until the next sunrise, after which it rots away to corruption in a single round, forcing the tuyewera to seek out a replacement before it regains its speech and attacks."}],"description":"The tuyewera is a hideous creation designed to serve not only as a stealthy minion but also as a monstrous assassin. Invisible during the day, a tuyewera can be sent into an enemy's lair to perform any number of missions desired by its creator or master. A tuyewera that lacks a master is a free-willed undead-in wilderness regions, it wanders aimlessly, constantly searching for signs of civilization. If it finds such signs, it invariably seeks out a graveyard and lurks in hiding, waiting for a new body to be buried so that it can burrow into the grave and steal the corpse's tongue at the first opportunity. The tuyewera then stalks the region, looking for mourners of the dead person to lure into a secluded area and suffocate, before stealing their tongues to repeat the process. Variant Tuyeweras The statistics presented are for a typical tuyewera created from the body of a Medium humanoid creature, but there are methods by which tuyeweras can be created from the bodies of smaller or larger humanoids as well. While in theory, one should be able to create a tuyewera from a non-humanoid creature, so far necromancers have been unable to achieve this feat. Something to do with the preparation method and the medicines used simply doesn't translate to non-humanoid bodies-although the unique undead created by such methods could have a variety of powers, they are not truly tuyeweras. Guidelines for statting up smaller and larger tuyeweras appear below. Smaller Tuyeweras: Tuyeweras created from the bodies of gnomes, half lings, or even children of larger humanoids can be statted up by applying the young creature simple template. Larger Tuyeweras: A tuyewera created from the body of a giant can be Large or larger. You can simply apply the giant creature simple template, but a better solution in this case is to rebuild the tuyewera with all of the appropriate changes to its stats-whenever a tuyewera's Hit Dice grant it an ability score increase, it increases its Charisma score. A Large tuyewera has 10 HD and is CR 6. A Huge one has 14 HD and is CR 8. A Gargantuan one has 18 HD and is CR 11. The largest, Colossal tuyeweras, have 22 HD and are CR 14. Creating a Tuyeweras A tuyewera can be created via the create undead spell, so long as the caster undertakes a specialized ritual as part of the casting. The body to be transformed into a tuyewera must be that of a humanoid the caster has himself slain at some point in the last 3 days. The spellcaster must be at least 13th level to create a tuyewera. Before the spellcasting begins, the caster must prepare the body by removing the corpse's tongue and severing its legs at the knees. The actual casting of the spell requires the caster to anoint the tuyewera's severed limbs and tongue with special medicines. These discarded body parts must then be burnt to ashes so that when the tuyewera rises from the dead, it doesn't recognize its missing limbs and tongue (if it does, it immediately attacks its creator). When the spell is complete, the newly created tuyewera is loyal to its creator and follows his spoken commands as long as the caster wears or carries a small pouch containing a handful of the ashes from the tuyewera's burnt limbs and tongue on his person. If the caster ever loses this pouch, the tuyewera becomes uncontrolled. If a tuyewera ever sees the ashes, it immediately recognizes them and seeks out its creator unerringly (as if via locate creature, but with no range limitation) and attempts to kill him- preferably as the creator sleeps.","ecology":"","habitat_society":""},{"name":"Udaeus","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"humanoid","subtypes":["mythic","udaeus"],"init":1,"senses":[{"type":"low-light vision"}],"ac":22,"ac_touch":11,"ac_flat_footed":21,"ac_mods":"+7 armor, +1 Dex, +1 natural, +3 shield","hp":38,"hd":"4d8+20","hdvalue":4,"hp_mods":["fast healing 1"],"fort":7,"ref":2,"will":2,"resists":[{"type":"fire","value":30}],"speed":[{"type":"land","speed":20}],"melee":"+1 shortspear +9 (1d6+6)","ranged":"mwk javelin +5 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"infuse arms and armor"},{"type":"mythic power","details":"1/day, surge +1d6"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"barkskin"},{"spell":"true strike"}]}],"strength":17,"dexterity":13,"constitution":16,"intelligence":10,"wisdom":12,"charisma":9,"baseatk":3,"cmb":6,"cmd":17,"feats":[{"feat":"Endurance","type":"bonus"},{"feat":"Weapon FocusM (shortspear)"},{"feat":"Weapon Specialization (shortspear)"}],"skills":[{"skill":"Intimidate","value":3},{"skill":"Perception","value":5}],"languages":["Celestial","Common"],"sq":[{"type":"armor and weapon training"},{"type":"fighter training"}],"environments":["any land","any urban"],"organizations":["solitary","pair","squadron (3-12)"],"treasure":"none","description_visual":"This armored humanoid has skin resembling white bone, carved with images of weapons and dragons.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Armor and Weapon Training","kind":"Ex","details":"Udaeoi are proficient with simple weapons, martial weapons, light armor, medium armor, heavy armor, and shields (including tower shields)."},{"type":"Energy Resistance","kind":"Ex","details":"An udaeus has resistance 30 against one type of energy. By performing a ritual that takes one day, an udaeus can change its energy resistance to a different energy type (either acid, cold, electricity, or fire). Most udaeoi choose fire resistance unless they expect to fight a creature using a specific energy type."},{"type":"Fighter Training","kind":"Ex","details":"An udaeus counts its racial Hit Dice as fighter levels for the purpose of qualifying for feats. If it has levels in fighter, these HIt Dice stack."},{"type":"Infuse Arms and Armor","kind":"Ex","details":"Any improvised weapon an udaeus wields is treated as a comparable normal weapon. Any normal weapon an udaeus wields is treated as a masterwork weapon. Any masterwork weapon it wields is treated as a weapon with a magical +1 enhancement bonus. Any weapon with a magical enhancement bonus it wields is treated as though its enhancement bonus were 1 higher than its actual value (to a maximum of +6). This ability also applies to armor and shields (normal is treated as masterwork, masterwork is treated as +1, and +1 or higher is treated as 1 higher than actual)."}],"description":"An udaeus (plural udaeoi) is a fierce humanoid who's obsessed with perfecting its skills at war. The first udaeoi were obedient warriors created by a deity out of dragon teeth, but now they are a distinct race and capable of reproducing on their own. Though an udaeus loves combat and is eager to demonstrate its abilities, it is violent only when it's in an honorable battle; only a desperate or manipulated udaeus would resort to thuggery. Udaeoi resemble tall, athletic humans with bone-white skin and black hair. They mark themselves with tattoos or brands, usually of weapons, dragons, or battle scenes. When an udaeus hardens its flesh with its innate magic, these markings look like carvings and cracks in a marble statue. Udaeoi might hire themselves out as mercenaries or serve as soldiers in a local army. Udaeoi prefer to fight alongside their own kind, and a squadron usually comprises members of the same fighting company or family unit.","ecology":"","habitat_society":"","gear":"mwk shortspear, mwk breastplate, mwk heavy steel shield, 4 javelins"},{"name":"Tinder Devil (Ukobach)","cr":4,"xp":1200,"alignment":"LE","size":"Small","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"}],"ac":17,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+4 Dex, +2 natural, +1 size","hp":32,"hd":"5d10+5","hdvalue":5,"fort":2,"ref":8,"will":7,"dr":"5/silver or good","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":15,"speed":[{"type":"land","speed":30}],"melee":"1 fire poker +5 (1d6-1 plus 1d4 fire) or 2 claws +5 (1d4- 1 plus 1d4 fire)","ranged":"1 ember +10 (1d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"animate flames"},{"type":"fire breathing"},{"type":"scorch"}],"strength":9,"dexterity":19,"constitution":13,"intelligence":13,"wisdom":16,"charisma":13,"baseatk":5,"cmb":3,"cmd":17,"feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Throw Anything"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Appraise","value":9},{"skill":"Bluff","value":9},{"skill":"Climb","value":7},{"skill":"Craft (any)","value":9},{"skill":"Knowledge (arcana)","value":9},{"skill":"Stealth","value":16}],"languages":["Celestial","Common","Infernal","telepathy 100 ft."],"sq":[{"type":"fire leap"}],"environments":["any (Hell)"],"organizations":["solitary","pair","team (4-16)"],"treasure":"standard","description_visual":"The light of a flaming pitchfork illuminates a creepily malformed little man, his red skin scarred and raw like the victim of horrific burns. Although barely taller than a child, his features mock those of a terrible old man with an oversized head, knife-like nose, and crazed round eyes flickering with wild flames.","group":"Devil","source":"AP 25","special_abilities":[{"type":"Animate Flames","kind":"Su","details":"As a standard action, an ukobach can animate an existing fire of Small size or larger. Doing so requires an ukobach to make a DC 15 Wisdom check as it impresses its will upon the fire. This DC increases by +5 for every size category of the flame above Small. If an ukobach succeeds, the flame animates with the statistics of a fire elemental of the same size, and follows the ukobach's mental commands. The flames remain animate for a number of rounds equal to the ukobach's Wisdom modifier-usually 3-after which they return to being simple flames, setting the square they cease moving in alight or being extinguished, as their surroundings warrant. Up to five ukobachs can make use of the aid another action to each grant an adjacent ukobach a +2 bonus on this Wisdom check to animate flames (granting a maximum +10 bonus)."},{"type":"Fire Leap","kind":"Su","details":"As a swift action, an ukobach occupying the same space as a fire, pool of lava, vent of searing steam, or similar blaze can teleport from that burning feature and emerge from another within 100 ft. This ability functions similarly to the spell dimension door, but only between fires. Upon entering a flame, an ukobach is instantly aware of all flames within range through which it might exit. If an ukobach enters a flame and there are no others to exit through within 100 ft., the devil's movement immediately ends and it is stunned for 1 round."},{"type":"Firebreathing","kind":"Su","details":"An ukobach can spend a standard action to guzzle a pint of oil, alcohol, or similarly flammable fluid and hold the combustible liquid within its body. At any point within 10 minutes of doing so, the ukobach can expel the liquid either as a 10-foot cone of fire or a 20-foot line of flame, both dealing 3d6 points of fire damage (Reflex DC 13 for half). Upon breathing fire an ukobach cannot make use of this ability again until it drinks another pint of oil. The save DC is Constitution-based."},{"type":"Scorch","kind":"Su","details":"An ukobach's touch is searing hot, causing its claws and any metal weapon it grasps to deal an additional 1d4 points of fire damage."}],"description":"Maniacal and clever, ukobachs embody the tenacity and ever advancing genius of Hell. Legions of these tiny devils labor throughout the it, and from their efforts rise new heresies and tools of depravity. They revel in the fires of Hell and manipulate them not toward destruction, but to the creation of ever greater and more innovative diabolical ends. The keepers of Hell's furnaces, they delight in their mad work, breaking only to torment the damned with their burning tools or newest inventions. Ukobachs stand approximately 3-1/2 ft. tall and weigh 70 pounds on average. Their fire pokers are fundamentally tied to their beings and disintegrate in a flash of cinders and ash upon the devil's death. These tools hold up to 10 fistsized embers, which an ukobach can fling at its enemies. Ecology Born from the burning depths of Hell, ukobachs find themselves most at home amid the choking and sultry pits where mortals dare not delve, proving well adapted to such stifling environs. While they must breathe, they prove equally well adapted to breathing smoke, cinders, and steam as air. Like all devils, the ukobachs' infernal eyes gaze through even the most stygian night, but unlike their brethren, they dislike the dark. While they harbor no fear of darkness and certainly see its value when tormenting mortals, they view it largely as a waste, seeking to dispel even the most fleeting shadow with an explosion of flame. Habitat & Society Most ukobachs originate from the flaming canals of Dis or the fiery pits of Phlegethon. Although rarely born from Moloch's crematoriums at the heart of Citadel Ba'al, hordes of ukobach furnace keepers tend the flames of the archdevil's ceremonial ovens. Devastating ukobach engineers also tinker in the foundries at the heart of Phlegethon, creating ingenious devices of intentional or incidental immolation-some infernal rumors claim a particularly insidious ukobach inspired the invention of the first fireworks, leaving these devils with a universal love of such creations. On the mortal plane, ukobachs gravitate to cities. While many metropolises prove ill prepared to defend against the flames these devils delight in spreading, most ukobachs take more subtle approaches, finding lairs in abandoned smithies, large furnaces, stone ruins, and other places likely to survive the occasional errant flame. While indisputably pyromaniacal, ukobachs are more than merely crazed marauders. Seeing a small hovel, pile of leaves, or alley cat burn isn'thing to creatures born from the flames of Hell. Rather, they enjoy the order and progression of flames, exalting in striking the spark that ignites a wildfire, upturning the lantern that sets a whole city quarter aflame, or immolating the leader whose death results in the dispersal of a formerly devout congregation. Further satisfying their methodological obsessions, ukobachs prefer setting elaborate traps for their victims over direct combat, often turning whole structures into burning deathtraps, trapping and retrapping the same location, or setting obvious snares that cause their quarries to overlook more devious ambushes. These impish devils understand the use of flammable fluids and materials well, often employing barrels of oil, casks of alcohol, heaps of coal, and even alchemical items like tindertwigs in their creations. Among diabolists, it is said that all ukobachs know the secret of creating berith, an alchemical element by which any material might be distilled into gold. Stories tell of ukobachs trading knowledge of this element for wild prices or only after an alchemist gathers components from exotic lands. Such tales often offer blatant moral lessons and warnings against these unnatural obsessions, such as the Taldan author and former alchemist Smardina's cryptic and symbol-laden work Shagreen, wherein an obsessed alchemist adventures across the world and ultimately trades an ukobach 23 years of his life, only to find his age and journeys have made his hands too crippled to work-he dies soon after and is dragged to Hell in a golden coffin. Summoning Ukobachs Ukobachs prove unusually congenial when it comes to answering the summons of many diabolists, especially those with an obvious creative streak, interest in alchemy, or queries regarding the inventions of Hell. Any diabolist who draws the magic circle necessary to bind an ukobach with mercury or silver powder, or who lights their diabolical summoning with chemical fire rather than normal oil or tinder, increases how difficult an ukobach finds it to escape from the magical trap by +2. Additionally, a diabolist gains a +2 bonus on the opposed Charisma check made to obtain an ukobach's service if the task involves creating alchemical or metallurgical works, or otherwise involves fire. In addition, ukobachs who know and favor their summoner sometimes bring gifts with them from Hell. While on the surface such boons might seem like blessings, they are always carefully selected by an ukobach and meant to encourage a summoner toward a destructive end. Commonly, such infernal gifts take the form of fireworks and explosives-especially in lands where such creations are uncommon-inscrutable blueprints or formulas for fiendish devices or magic items, or powerfully volatile alchemical reagents.","ecology":"Born from the burning depths of Hell, ukobachs find themselves most at home amid the choking and sultry pits where mortals dare not delve, proving well adapted to such stifling environs. While they must breathe, they prove equally well adapted to breathing smoke, cinders, and steam as air. Like all devils, the ukobachs' infernal eyes gaze through even the most stygian night, but unlike their brethren, they dislike the dark. While they harbor no fear of darkness and certainly see its value when tormenting mortals, they view it largely as a waste, seeking to dispel even the most fleeting shadow with an explosion of flame.","habitat_society":"Most ukobachs originate from the flaming canals of Dis or the fiery pits of Phlegethon. Although rarely born from Moloch's crematoriums at the heart of Citadel Ba'al, hordes of ukobach furnace keepers tend the flames of the archdevil's ceremonial ovens. Devastating ukobach engineers also tinker in the foundries at the heart of Phlegethon, creating ingenious devices of intentional or incidental immolation-some infernal rumors claim a particularly insidious ukobach inspired the invention of the first fireworks, leaving these devils with a universal love of such creations. On the mortal plane, ukobachs gravitate to cities. While many metropolises prove ill prepared to defend against the flames these devils delight in spreading, most ukobachs take more subtle approaches, finding lairs in abandoned smithies, large furnaces, stone ruins, and other places likely to survive the occasional errant flame. While indisputably pyromaniacal, ukobachs are more than merely crazed marauders. Seeing a small hovel, pile of leaves, or alley cat burn isn'thing to creatures born from the flames of Hell. Rather, they enjoy the order and progression of flames, exalting in striking the spark that ignites a wildfire, upturning the lantern that sets a whole city quarter aflame, or immolating the leader whose death results in the dispersal of a formerly devout congregation. Further satisfying their methodological obsessions, ukobachs prefer setting elaborate traps for their victims over direct combat, often turning whole structures into burning deathtraps, trapping and retrapping the same location, or setting obvious snares that cause their quarries to overlook more devious ambushes. These impish devils understand the use of flammable fluids and materials well, often employing barrels of oil, casks of alcohol, heaps of coal, and even alchemical items like tindertwigs in their creations. Among diabolists, it is said that all ukobachs know the secret of creating berith, an alchemical element by which any material might be distilled into gold. Stories tell of ukobachs trading knowledge of this element for wild prices or only after an alchemist gathers components from exotic lands. Such tales often offer blatant moral lessons and warnings against these unnatural obsessions, such as the Taldan author and former alchemist Smardina's cryptic and symbol-laden work Shagreen, wherein an obsessed alchemist adventures across the world and ultimately trades an ukobach 23 years of his life, only to find his age and journeys have made his hands too crippled to work-he dies soon after and is dragged to Hell in a golden coffin. Summoning Ukobachs Ukobachs prove unusually congenial when it comes to answering the summons of many diabolists, especially those with an obvious creative streak, interest in alchemy, or queries regarding the inventions of Hell. Any diabolist who draws the magic circle necessary to bind an ukobach with mercury or silver powder, or who lights their diabolical summoning with chemical fire rather than normal oil or tinder, increases how difficult an ukobach finds it to escape from the magical trap by +2. Additionally, a diabolist gains a +2 bonus on the opposed Charisma check made to obtain an ukobach's service if the task involves creating alchemical or metallurgical works, or otherwise involves fire. In addition, ukobachs who know and favor their summoner sometimes bring gifts with them from Hell. While on the surface such boons might seem like blessings, they are always carefully selected by an ukobach and meant to encourage a summoner toward a destructive end. Commonly, such infernal gifts take the form of fireworks and explosives-especially in lands where such creations are uncommon-inscrutable blueprints or formulas for fiendish devices or magic items, or powerfully volatile alchemical reagents."},{"name":"Umasi","cr":4,"xp":1200,"alignment":"CN","size":"Medium","type":"monstrous humanoid","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +4 natural, +2 shield","hp":42,"hd":"5d10+15","hdvalue":5,"fort":6,"ref":6,"will":5,"save_mods":"+2 vs. poison","immunities":["disease"],"weaknesses":["immune to healing"],"speed":[{"type":"land","speed":40}],"melee":"dagger +7 (1d4+4/19-20), 2 unarmed strikes +7 (1d3+2  nonlethal)","ranged":"shortbow +7 (1d6/x3)","space":"5 ft.","reach":"5 ft.","strength":18,"dexterity":15,"constitution":17,"intelligence":10,"wisdom":13,"charisma":8,"baseatk":5,"cmb":9,"cmd":21,"feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Multiweapon Fighting"}],"skills":[{"skill":"Heal","value":13},{"skill":"Intimidate","value":6},{"skill":"Perception","value":12},{"skill":"Stealth","value":11},{"skill":"Survival","value":8}],"languages":["Polyglot"],"sq":[{"type":"graft flesh"},{"type":"harvest organs"},{"type":"immortal flesh"}],"environments":["tropical jungles"],"organizations":["solitary","hunting party (2-8)","tribe (10-30)"],"treasure":"none","description_visual":"An emaciated humanoid bursts through the trees, brandishing a knife of black stone. His body is a patchwork of hair, skin, scales, and strange limbs stitched together with thick, black thread.","source":"AP 39","special_abilities":[{"type":"Graft Flesh","kind":"Su","details":"Umasi can graft the flesh and even limbs of other humanoids to their own bodies in a ritual that takes 1 hour to complete. To heal damage, an Umasi must have a supply of flesh (either living or dead), and the Umasi must make a DC 20 Heal check to treat deadly wounds. The Umasi can only heal damage with his graft flesh ability once per day, but there is no time limit on healing wounds and the Umasi doesn't need a healer's kit (and doesn't take a penalty for lacking one). This ability otherwise functions as the treat deadly wounds use of the Heal skill. Umasi can also graft additional limbs onto their bodies; each extra arm gives the Umasi an additional unarmed strike, while each additional leg adds +5 ft. to the Umasi's speed. An Umasi can have a maximum of six arms and six legs."},{"type":"Harvest Organs","kind":"Su","details":"An Umasi can remove a vital organ when he delivers a coup de grace against a humanoid opponent with a slashing or piercing weapon. The next round, the Umasi can consume the harvested organ as a move action to gain the benefits of the death knell spell (caster level equal to the Umasi's Hit Dice)."},{"type":"Immortal Flesh","kind":"Su","details":"Umasi are immune to disease and aging effects, and they gain a +2 racial bonus on saving throws against poison."},{"type":"Immune to Healing","kind":"Ex","details":"Umasi don't heal damage naturally, and are not healed by positive or negative energy."}],"description":"Reclusive and shrouded in mystery, the Umasi-or Harvestmen, as they are known across the Mwangi Expanse-are a race of humanoids who exist between life and death. Unable to heal or procreate naturally, the Umasi extend their lives by transplanting the skin, organs, or even entire appendages of other humanoids onto parts of their own bodies. As a result, there is no typical description for a Harvestman-each is a patchwork conglomeration of different features, though most Umasi have multiple limbs of varying sizes. The need to use body parts of generally the same size and shape makes most Umasi human-sized; few are over 6 ft. tall. Most weigh between 150 and 300 pounds, and the constant addition of new flesh has left little distinction between genders.\n\nEcology Zenj legends say the Umasi were an ancient tribe of arrogant scholars who lived deep in the Mwangi Jungle. When a powerful witch doctor came to the Umasi seeking their wisdom, he was rebuffed as being unworthy of receiving the Umasi's knowledge. Enraged, the witch doctor used a taboo ritual to curse the Umasi, stealing away fragments of their very souls and binding them to the flesh of others, forcing them to harvest the bodies of humanoids to sustain a bitterly extended existence. This curse left the Umasi a sterile, aff licted people somewhere between the living and the living dead.\n\nContrary to their appearance, Umasi are living creatures.\n\nThey eat, breathe, and sleep like other humanoids, but their bodies are in a constant state of decay. This divided nature grants the Harvestmen immunity to disease and resistance to toxins, but even minor injuries don't heal naturally; Umasi must graft new flesh onto existing tissue to heal their wounds.\n\nStaving off the endless decay of their bodies requires more extreme measures. As limbs and organs rot, Umasi elders use obsidian blades to remove the subject's decaying parts, replacing them with similar parts from fresh corpses and linking the replacements to the original body through a complex ritual combining ancient Umasi knowledge with the forbidden juju rites of their original curser. When the ritual is complete, the new body part joins perfectly with the Umasi and death is cheated… for a time.\n\nIn much the same way, Harvestmen are not born, but made. Barren, infertile, and missing pieces of their souls,\n\nUmasi are unable to breed. Their only recourse is to tear off chunks of their own flesh, bind them together with the remains of dead humanoids, and animate the results using the same ancient juju rites.\n\nMany people have sought the secret to the longevity of the Harvestmen, only to be turned away with little explanation. Because the joining ritual requires one to give away a part of his soul willingly, the Umasi only accept those ready to make such a dire compact because they have no other choice. The Harvestmen only give their \"gift\" to humanoids who find themselves at the edge of death, whether from a grievous wound or some magically resistant aff liction or disease. During the ritual, a piece of the dying humanoid is exchanged with a corresponding piece of an Umasi \"donor.\" Once the stitches are sewn, the dying creature's wounds are healed, and he joins the ranks of the Harvestmen forevermore.\n\nHabitat and Society Umasi society is as much a patchwork as its members. Some live off the jungle, hunting and farming as they did before the curse. Other tribes lead sedentary lives, trading ancient artifacts of the first Umasi with explorers in exchange for needed goods. Umasi have no organized leadership or traditional families, and children are unheard of among their kind. Regardless, all Umasi tribes form around a council of elders.\n\nWhile some Umasi still dwell deep in the Mwangi Jungle amid the skeletal ruins of their former kingdom, the majority of the Harvestmen have spread to the Kaava Lands and the Screaming Jungle, distancing themselves from the memory of their curse. Umasi are reclusive wherever they dwell, preferring to stay on the fringes of settlements. Although they need humanoid flesh to survive, most Umasi kill only as a last resort, taking flesh from the newly dead instead. This practice often stigmatizes them further, with other races considering them little more than grave robbers. A few Umasi embrace their near immortality in a darker way, viewing other humanoids as prey. These Harvestmen roam the Bandu Hills with undead ghouls, hunting travelers and harvesting what they wish, sometimes before their victims are even dead.\n\nHowever, some Umasi use their peculiar nature to live harmoniously with other humanoids. Pathfinders tell of human villages where Umasi act as gravediggers during plague outbreaks. Their immunity to disease allows the Harvestmen to safely dispose of infected corpses, while at the same time gaining the flesh they need and also garnering goodwill from those they help.\n\nHarvestmen rarely fight with other races, but competition over resources like water or hunting grounds can cause conf lict, and those knowingly trespassing on Umasi land may court their anger. When driven to combat, Umasi are extremely dangerous, laying ambushes for enemies and swarming their targets in the hope of harvesting their strength. With their obsidian blades, Harvestmen can punch through the chest cavities of helpless or dying humanoids to extract vital organs. Any Umasi who consumes these pieces of their victims gains a ferocious surge of power, turning the tide of even a desperate battle.\n\nAll Harvestmen know the heavy price they pay to cheat death. Some, over the lonely centuries, have come to regret their existence, roaming the lengths of the Mwangi Expanse and beyond in search of powerful magic to free them from their curse. Sadly, no mortal magic has yet proven strong enough to undo the fell curse of the Umasi.","ecology":"Zenj legends say the Umasi were an ancient tribe of arrogant scholars who lived deep in the Mwangi Jungle. When a powerful witch doctor came to the Umasi seeking their wisdom, he was rebuffed as being unworthy of receiving the Umasi's knowledge. Enraged, the witch doctor used a taboo ritual to curse the Umasi, stealing away fragments of their very souls and binding them to the flesh of others, forcing them to harvest the bodies of humanoids to sustain a bitterly extended existence. This curse left the Umasi a sterile, aff licted people somewhere between the living and the living dead.\n\nContrary to their appearance, Umasi are living creatures.\n\nThey eat, breathe, and sleep like other humanoids, but their bodies are in a constant state of decay. This divided nature grants the Harvestmen immunity to disease and resistance to toxins, but even minor injuries don't heal naturally; Umasi must graft new flesh onto existing tissue to heal their wounds.\n\nStaving off the endless decay of their bodies requires more extreme measures. As limbs and organs rot, Umasi elders use obsidian blades to remove the subject's decaying parts, replacing them with similar parts from fresh corpses and linking the replacements to the original body through a complex ritual combining ancient Umasi knowledge with the forbidden juju rites of their original curser. When the ritual is complete, the new body part joins perfectly with the Umasi and death is cheated… for a time.\n\nIn much the same way, Harvestmen are not born, but made. Barren, infertile, and missing pieces of their souls,\n\nUmasi are unable to breed. Their only recourse is to tear off chunks of their own flesh, bind them together with the remains of dead humanoids, and animate the results using the same ancient juju rites.\n\nMany people have sought the secret to the longevity of the Harvestmen, only to be turned away with little explanation. Because the joining ritual requires one to give away a part of his soul willingly, the Umasi only accept those ready to make such a dire compact because they have no other choice. The Harvestmen only give their \"gift\" to humanoids who find themselves at the edge of death, whether from a grievous wound or some magically resistant aff liction or disease. During the ritual, a piece of the dying humanoid is exchanged with a corresponding piece of an Umasi \"donor.\" Once the stitches are sewn, the dying creature's wounds are healed, and he joins the ranks of the Harvestmen forevermore.\n\nHabitat and Society Umasi society is as much a patchwork as its members. Some live off the jungle, hunting and farming as they did before the curse. Other tribes lead sedentary lives, trading ancient artifacts of the first Umasi with explorers in exchange for needed goods. Umasi have no organized leadership or traditional families, and children are unheard of among their kind. Regardless, all Umasi tribes form around a council of elders.\n\nWhile some Umasi still dwell deep in the Mwangi Jungle amid the skeletal ruins of their former kingdom, the majority of the Harvestmen have spread to the Kaava Lands and the Screaming Jungle, distancing themselves from the memory of their curse. Umasi are reclusive wherever they dwell, preferring to stay on the fringes of settlements. Although they need humanoid flesh to survive, most Umasi kill only as a last resort, taking flesh from the newly dead instead. This practice often stigmatizes them further, with other races considering them little more than grave robbers. A few Umasi embrace their near immortality in a darker way, viewing other humanoids as prey. These Harvestmen roam the Bandu Hills with undead ghouls, hunting travelers and harvesting what they wish, sometimes before their victims are even dead.\n\nHowever, some Umasi use their peculiar nature to live harmoniously with other humanoids. Pathfinders tell of human villages where Umasi act as gravediggers during plague outbreaks. Their immunity to disease allows the Harvestmen to safely dispose of infected corpses, while at the same time gaining the flesh they need and also garnering goodwill from those they help.\n\nHarvestmen rarely fight with other races, but competition over resources like water or hunting grounds can cause conf lict, and those knowingly trespassing on Umasi land may court their anger. When driven to combat, Umasi are extremely dangerous, laying ambushes for enemies and swarming their targets in the hope of harvesting their strength. With their obsidian blades, Harvestmen can punch through the chest cavities of helpless or dying humanoids to extract vital organs. Any Umasi who consumes these pieces of their victims gains a ferocious surge of power, turning the tide of even a desperate battle.\n\nAll Harvestmen know the heavy price they pay to cheat death. Some, over the lonely centuries, have come to regret their existence, roaming the lengths of the Mwangi Expanse and beyond in search of powerful magic to free them from their curse. Sadly, no mortal magic has yet proven strong enough to undo the fell curse of the Umasi.","habitat_society":"","gear":"heavy wooden shield, obsidian dagger,  shortbow and 20 arrows"},{"name":"Vampire Spawn","cr":4,"xp":1200,"alignment":"LE","size":"Medium","type":"undead","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+1 Dex, +4 natural","hp":26,"hd":"4d8+8","hdvalue":4,"hp_mods":["fast healing 2"],"fort":3,"ref":2,"will":1,"defensive_abilities":["channel resistance +2"],"dr":"5/silver","immunities":["undead traits"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10}],"weaknesses":["resurrection vulnerability","vampire weaknesses"],"speed":[{"type":"land","speed":30}],"melee":"slam +4 (1d4+1 plus energy drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain"},{"type":"dominate","details":"DC 14"},{"type":"energy drain","details":"1 level, DC 14"}],"strength":12,"dexterity":12,"intelligence":11,"wisdom":13,"charisma":15,"baseatk":3,"cmb":4,"cmd":16,"feats":[{"feat":"Blind-Fight"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Intimidate","value":2},{"skill":"Knowledge (religion)","value":7},{"skill":"Perception","value":11},{"skill":"Stealth","value":16}],"languages":["Common"],"sq":[{"type":"gaseous form"},{"type":"shadowless"},{"type":"spider climb"}],"environments":["any"],"organizations":["solitary","pair","gang (3-6)","pack (7-12)"],"treasure":"Value standard","description_visual":"This alluring, raven-haired beauty casually wipes a trickle of blood from a pale cheek, then smiles to reveal needle-sharp fangs.","source":"PFRPG Bestiary","special_abilities":[{"type":"Blood Drain","kind":"Su","details":"A vampire spawn can suck blood from a grappled opponent; if the vampire spawn establishes or maintains a pin, it drains blood, dealing 1d4 points of Constitution damage. The vampire spawn heals 5 hit points or gains 5 temporary hit points for 1 hour (up to a maximum number of temporary hit points equal to its full normal hit points) each round it drains blood."},{"type":"Dominate","kind":"Su","details":"A vampire spawn can crush a humanoid opponent's will as a standard action. Anyone the vampire spawn targets must succeed on a Will save (DC 14) or fall instantly under the vampire spawn's influence, as though by a dominate person spell (caster level 12th). The ability has a range of 30 ft. At the GM's discretion, some vampire spawns might be able to affect different creature types with this power."},{"type":"Energy Drain","kind":"Su","details":"A creature hit by a vampire spawn's slam (or other natural weapon) gains one negative level. This ability only triggers once per round, regardless of the number of attacks a vampire spawn makes."},{"type":"Fast Healing","kind":"Su","details":"A vampire spawn also gains fast healing 2. If reduced to 0 hit points in combat, a vampire spawn assumes gaseous form and attempts to escape. It must reach its coffin home within 2 hours or be utterly destroyed. (It can normally travel up to 9 miles in 2 hours.) Additional damage dealt to a vampire spawn forced into gaseous form has no effect. Once at rest, the vampire is helpless. It regains 1 hit point after 1 hour, then is no longer helpless and resumes healing at the rate of 2 hit points per round."},{"type":"Gaseous Form","kind":"Su","details":"As a standard action, a vampire spawn can assume gaseous form at will (caster level 5th), but it can remain gaseous indefinitely and has a fly speed of 20 ft. with perfect maneuverability."},{"type":"Resurrection Vulnerability","kind":"Su","details":"A raise dead or similar spell cast on a vampire spawn destroys it (Will negates). Using the spell in this way doesn't require a material component."},{"type":"Shadowless","kind":"Ex","details":"A vampire spawn casts no shadows and shows no reflection in a mirror."},{"type":"Spider Climb","kind":"Ex","details":"A vampire spawn can climb sheer surfaces as though under the effects of a spider climb spell. Weaknesses Vampire spawns cannot tolerate the strong odor of garlic and will not enter an area laced with it. Similarly, they recoil from mirrors or strongly presented holy symbols. These things don't harm the vampire spawn-they merely keep it at bay. A recoiling vampire spawn must stay at least 5 ft. away from the mirror or holy symbol and cannot touch or make melee attacks against that creature. Holding a vampire spawn at bay takes a standard action. After 1 round, a vampire spawn can overcome its revulsion of the object and function normally each round it makes a DC 25 Will save."}],"description":"Vampire spawns cannot enter a private home or dwelling unless invited in by someone with the authority to do so.\n\nReducing a vampire spawn's hit points to 0 or lower incapacitates it but doesn't always destroy it (see fast healing). However, certain attacks can slay vampire spawns. Exposing any vampire spawn to direct sunlight staggers it on the first round of exposure and destroys it utterly on the second consecutive round of exposure if it doesn't escape. Each round of immersion in running water inflicts damage on a vampire spawn equal to one-third of its maximum hit points-a vampire spawn reduced to 0 hit points in this manner is destroyed. Driving a wooden stake through a helpless vampire spawn's heart instantly slays it (this is a full-round action). However, it returns to life if the stake is removed, unless the head is also severed and anointed with holy water.","ecology":"","habitat_society":""},{"name":"Vendenopterix","cr":4,"xp":1200,"alignment":"CN","size":"Medium","type":"outsider","subtypes":["chaotic","extraplanar","shapechanger"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+3 Dex, +1 dodge, +4 natural","hp":39,"hd":"6d10+6","hdvalue":6,"fort":3,"ref":8,"will":7,"save_mods":"+2 vs. enchantments","dr":"5/cold iron","immunities":["sleep"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":5}],"sr":15,"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"average"}],"melee":"2 claws +9 (1d6+1 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"ability drain"},{"type":"poison"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dimension door"},{"spell":"ethereal jaunt","details":"self plus 50 lbs. of objects only"},{"spell":"heightened charm person"},{"spell":"suggestion"}]},{"frequency":"3/day","spells":[{"spell":"charm person"},{"spell":"darkness"},{"spell":"locate creature"}]}],"strength":13,"dexterity":16,"constitution":13,"intelligence":10,"wisdom":11,"charisma":14,"baseatk":6,"cmb":7,"cmd":21,"feats":[{"feat":"Dodge"},{"feat":"Iron Will"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":11,"special":"+19 when passing hidden messages"},{"skill":"Diplomacy","value":11},{"skill":"Disguise","value":11},{"skill":"Knowledge (planes)","value":6},{"skill":"Perception","value":9},{"skill":"Perform (dance)","value":8},{"skill":"Survival","value":9,"special":"+13 when tracking"}],"languages":["Abyssal","Celestial","Common","Draconic","Elven","telepathy 10 ft."],"sq":[{"type":"change shape","details":"any humanoid; alter self"},{"type":"swift tracker"}],"environments":["any (Elysium)"],"organizations":["solitary","pair"],"treasure":"standard","description_visual":"This elven woman's allure is obfuscated by her ragged insectile wings and long, clawlike nails.","source":"Inner Sea Gods","special_abilities":[{"type":"Ability Drain","kind":"Su","details":"A vendenopterix drains energy from a mortal she lures into an act of passion, such as a kiss. An unwilling victim must be grappled before the vendenopterix can use this ability. The vendenopterix's kiss inflicts 1 point of Intelligence, Wisdom, or Charisma drain (her choice). The kiss also has the effect of a suggestion spell, asking the victim to accept another act of passion from the vendenopterix. The target must succeed at a DC 15 Will save to negate the suggestion. The save DC is Charisma-based."},{"type":"Poison","kind":"Ex","details":"Claw-injury; save Fort DC 16; frequency 1/round for 6 rounds; effect 1d2 Dex damage; cure 2 consecutive saves. The save DC is Constitution-based, and includes a +2 racial bonus."},{"type":"Swift Tracker","kind":"Ex","details":"A vendenopterix can move at her normal speed while using Survival to follow tracks without taking the normal -5 penalty. She takes only a -10 penalty (instead of the normal -20 penalty) when moving at up to twice her normal speed while tracking."}],"description":"Beautiful, seductive, and ruthless, vendenopterixes are servitors of Calistria tasked with hunting down and punishing enemies of the faith. Though they typically take female form, vendenopterixes are comfortable taking the shape of any gendered humanoid (including polygendered creatures) but avoid genderless shapes. A vendenopterix's purpose is to punish, but not necessarily to kill. She may be tasked with exposing a creature's secrets or convincing a creature to do so itself in an embarrassing way, and she is just as likely to drain her victim's mental facilities until it acts like a buffoon or clod as she is to poison her target so it appears to be aff licted with (or even dying from) a venereal pox. Vendenopterixes stand about 6 ft. tall and range in weight from a slender 140 pounds to a curvaceous 240.","ecology":"","habitat_society":""},{"name":"Venomous Snake Swarm","cr":4,"xp":1200,"alignment":"N","size":"Tiny","type":"animal","subtypes":["swarm"],"init":7,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+3 Dex, +2 natural, +2 size","hp":37,"hd":"5d8+15","hdvalue":5,"fort":7,"ref":9,"will":2,"defensive_abilities":["swarm traits"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20},{"type":"swim","speed":10}],"melee":"swarm (1d6 plus distraction and poison)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 15"}],"strength":9,"dexterity":16,"constitution":17,"intelligence":1,"wisdom":12,"charisma":2,"baseatk":3,"feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":7,"special":"+3 when jumping"},{"skill":"Climb","value":15},{"skill":"Perception","value":13},{"skill":"Stealth","value":19},{"skill":"Swim","value":11}],"environments":["any"],"organizations":["solitary","nest (2-4 swarms)","knot (5-7 swarms)"],"treasure":"none","description_visual":"Venomous snakes slither and crawl over each other in a furious mass, their poison-dripping fangs glinting in the light.","group":"Snake Swarm","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Poison","kind":"Ex","details":"Swarm-injury; save Fort DC 15; frequency 1/round for 6 rounds; effect 1d2 Con damage; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"While all snake swarms are dangerous, swarms made up of venomous snakes are typically the most lethal. Snake swarms of both types can generally be encountered in the same regions, dwelling in ruins or wilderness alike.","ecology":"","habitat_society":""},{"name":"Very Young White Dragon","cr":4,"xp":1200,"alignment":"CE","size":"Small","type":"dragon","subtypes":["cold"],"init":6,"senses":[{"type":"dragon senses"},{"type":"snow vision"}],"ac":18,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+2 Dex, +5 natural, +1 size","hp":42,"hd":"5d12+10","hdvalue":5,"fort":6,"ref":6,"will":4,"immunities":["cold","paralysis","sleep"],"weaknesses":["Vulnerability to fire"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":30},{"type":"fly","speed":150,"maneuverability":"average"},{"type":"swim","speed":60}],"melee":"bite +8 (1d6+3), 2 claws +8 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"20-ft. cone, DC 14, 4d4 cold"}],"strength":15,"dexterity":14,"constitution":15,"intelligence":8,"wisdom":11,"charisma":8,"baseatk":5,"cmb":6,"cmd":18,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Fly","value":12},{"skill":"Intimidate","value":7},{"skill":"Perception","value":10},{"skill":"Stealth","value":14},{"skill":"Swim","value":18}],"languages":["Draconic"],"sq":[{"type":"icewalking"}],"environments":["cold mountains"],"organizations":["solitary"],"treasure":"triple","description_visual":"This dragon's scales are a frosty white. Its head is crowned with slender horns, with a thin membrane stretched between them.","group":"Chromatic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Icewalking","kind":"Ex","details":"This ability works like the spider climb spell, but the surfaces the dragon climbs must be icy. The dragon can move across icy surfaces without penalty and doesn't need to make Acrobatics checks to run or charge on ice."},{"type":"Snow Vision","kind":"Ex","details":"A very young white dragon learns to see perfectly well in snowy conditions. A white dragon doesn't suffer any penalties to Perception checks while in snow."}],"description":"Although most consider it to be the weakest and most feral of the chromatic dragons, the white dragon makes up for its lack of cunning with sheer ferocity. White dragons dwell on remote, frozen mountaintops and in arctic lowlands, making their home in glittering caves full of ice and snow. They prefer their meals completely frozen.","ecology":"","habitat_society":""},{"name":"Viduus","cr":4,"xp":1200,"alignment":"N","size":"Medium","type":"outsider","subtypes":["extraplanar","psychopomp"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"spiritsense"}],"ac":16,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+6 natural","hp":47,"hd":"5d10+20","hdvalue":5,"fort":5,"ref":4,"will":10,"immunities":["death effects","disease","mind-affecting effects","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10}],"sr":15,"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"quill +5 (1d4 plus censor or expurgate)","space":"5 ft.","reach":"5 ft.","strength":10,"dexterity":11,"constitution":18,"intelligence":15,"wisdom":19,"charisma":16,"baseatk":5,"cmb":5,"cmd":15,"feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Iron Will"}],"skills":[{"skill":"Bluff","value":11},{"skill":"Climb","value":8},{"skill":"Diplomacy","value":11},{"skill":"Knowledge (history)","value":10},{"skill":"Knowledge (planes)","value":10},{"skill":"Knowledge (religion)","value":10},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":14},{"skill":"Stealth","value":8}],"languages":["Abyssal","Celestial","Common","Infernal"],"sq":[{"type":"spirit touch"},{"type":"transformation"}],"environments":["any (the Boneyard)"],"organizations":["solitary","pair","library (3-12)"],"treasure":"standard","description_visual":"This dour being has a mostly humanoid form enwrapped in a cocoonlike lower body, and wields a large quill.","group":"Psychopomp","source":"Inner Sea Bestiary","special_abilities":[{"type":"Censor","kind":"Su","details":"A viduus that strikes a living creature with its quill can rewrite that creature's memories. The creature must succeed at a DC 15 Will save or have its memories affected in a manner similar to the spell modify memory. The viduus can rewrite 1 day's worth of the target's memories with a single strike. As a result, the creature is either stunned or confused for the next 1d4 rounds (50% chance of either). At the GM's discretion, this might have longer-term effects. A creature's memories can be restored by lesser restoration, modify memory, or similar spells. Memories lost in this manner are copied into one of the numerous tomes protected by the viduus. This is a mind-affecting effect. The DC is Charisma-based."},{"type":"Expurgate","kind":"Su","details":"A viduus that strikes a dead creature-such as a soul, petitioner, or undead creature-with its quill can obliterate that creature's memories. The creature must succeed at a DC 15 Will save or have all of its memories erased. It retains language and basic knowledge, but no details as to the events of its life. This typically leaves the creature calm and indifferent to all beings around it. This memory loss is permanent, though the memories can be restored by lesser restoration, modify memory, or similar spells. Memories lost in this manner are copied into one of the numerous tomes protected by the viduus. This is a mind-affecting effect. The DC is Charisma-based."},{"type":"Transformation","kind":"Su","details":"A viduus that is reduced to 0 hit points transforms. Its cocoon body bursts open, expelling a swarm of biting white-and-black centipedes (same statistics as a spider swarm) and a bank of mind fog centered on the viduus's square. A viduus can purposefully transform by spending three consecutive full-round actions, in which case it reforms somewhere in the Boneyard 1 month later."}],"description":"Viduuses occupy the libraries and scriptoriums located atop Pharasma's spire. While lesser psychopomps record every soul's death and ultimate fate upon the planes, viduuses are interested in more extraordinary souls-their lives, deeds, deaths, and secrets. Existence holds many mysteries, and those mortals who had brushes with the extraordinary have their tales and confessions recorded by these semi-cocooned scholars and added to the volumes of the Boneyard's expansive library, known as the Catalogue of Last Days. Although pretentious in the extreme, viduuses prove quite knowledgeable about many historical and planar secrets, and what they don't know they generally have a decent idea of how to research, potentially summoning assistants from across the planes to aid them.","ecology":"","habitat_society":""},{"name":"Voonith","cr":4,"xp":1200,"alignment":"CN","size":"Small","type":"magical beast","subtypes":["aquatic"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+3 Dex, +3 natural, +1 size","hp":37,"hd":"5d10+10","hdvalue":5,"fort":6,"ref":7,"will":2,"speed":[{"type":"land","speed":30},{"type":"swim","speed":50}],"melee":"bite +8 (1d6+1 plus trip), 4 claws +7 (1d3+1)","space":"5 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"blood-freezing howl"},{"type":"pounce"}],"strength":13,"dexterity":16,"constitution":14,"intelligence":5,"wisdom":12,"charisma":13,"baseatk":5,"cmb":5,"cmd":18,"cmd_special":"+8 vs. trip","feats":[{"feat":"Ability Focus (blood-freezing howl)"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":8},{"skill":"Stealth","value":12},{"skill":"Swim","value":14}],"languages":["Aklo"],"sq":[{"type":"amphibious"}],"environments":["any marshes","any rivers"],"organizations":["solitary","pair","clutch (3-6)"],"treasure":"standard","description_visual":"This brightly colored, long-necked amphibian has six legs, a fanged snout, and numerous finlets running down its spine.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Blood-Freezing Howl","kind":"Su","details":"As a standard action, a voonith can unleash a bloodcurdling howl. All creatures within a 30-foot-radius burst must succeed at a DC 15 Will save or become dazed for 1 round and then shaken for an additional 1d6 rounds. Any creature that makes a successful save against a voonith's howl is immune to the same voonith's howl for 24 hours. This is a sonic mind-affecting fear effect. The save DC is Charisma-based."}],"description":"Cunning and aggressive, vooniths are amphibious nocturnal predators with voracious appetites and mild intelligence. A voonith's howl is said to freeze the blood and is more than capable of stopping a creature in its tracks. Vooniths usually howl when they see prey too far away from the water's edge to ambush. While the vooniths are native to the strange Dimension of Dream, many have found their way out of that realm and into the waking world to take up lairs in the swampy fens and remote coastlines of the world. How the vooniths originally managed to make this transition between worlds is unclear.\n\nAlthough they look like little more than wild beasts, vooniths are actually rather intelligent. While certainly not as sharp as the average human, a voonith is smart enough to know how to speak and often does so with others of its kind. Vooniths don't often choose to communicate with other creatures, giving rise to the misconception that they're little more than dumb animals, but on occasion, travelers in swampy regions tell tales of overhearing strange piping voices speaking among the reeds. Those few who know the secrets of the Aklo tongue can understand these words, although understanding of what the vooniths whisper in the night when they think no one else can hear isn't always for the best.\n\nWhile not evil, vooniths have a decidedly dark sense of humor, and take great pleasure in concocting violent poems or grisly jokes. Punch lines in which non-voonith creatures-particularly humans, cats, and gnomes- meet gory and ironic fates are the most entertaining to vooniths. Some tales speak of canny travelers who, with the ability to speak Aklo, manage to strike up unlikely conversations with lurking vooniths. In truth, vooniths are quite social, and when one breeches the awkwardness arising from interspecies conf lict, a friendship with a voonith can be an unexpected reward. Vooniths who befriend travelers often escort them, quietly and unseen, through dangerous bogs, and when such travelers fall prey to other dangers of the swamp, a friendly voonith will provide what aid it can.\n\nVooniths are 4 ft. long and weigh 70 pounds, yet rumors tell of vooniths that have grown to much larger sizes than this.","ecology":"","habitat_society":""},{"name":"Vulnudaemon","cr":4,"xp":1200,"alignment":"NE","size":"Small","type":"outsider","subtypes":["daemon","evil","extraplanar"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect magic"}],"auras":["aura of doom (30 ft., DC 18)"],"ac":17,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+3 Dex, +3 natural, +1 size","hp":39,"hd":"6d10+6","hdvalue":6,"fort":6,"ref":5,"will":6,"dr":"5/good or silver","immunities":["acid","death effects","disease","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":30}],"melee":"short sword +10 (1d4+2/19-20 plus bleed), bite +5 (1d3+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"1d4"},{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"1/day","spells":[{"spell":"inflict critical wounds"},{"spell":"summon","details":"level 2, 1d4 cacodaemons 40%"}]},{"frequency":"3/day","spells":[{"spell":"blur"},{"spell":"death knell"},{"spell":"invisibility"},{"spell":"minor image"}]}],"strength":14,"dexterity":17,"constitution":13,"intelligence":12,"wisdom":13,"charisma":16,"baseatk":6,"cmb":7,"cmd":20,"feats":[{"feat":"Ability Focus (aura of doom)"},{"feat":"Combat Casting"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":12},{"skill":"Diplomacy","value":10},{"skill":"Fly","value":11},{"skill":"Knowledge (arcana)","value":7},{"skill":"Knowledge (planes)","value":8},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":10},{"skill":"Spellcraft","value":8},{"skill":"Stealth","value":16}],"languages":["Abyssal","Draconic","Infernal","telepathy 100 ft."],"environments":["any (Abaddon)"],"organizations":["solitary","pair","murder (3-12)"],"treasure":"standard","description_visual":"A bloody, tooth-filled mouth that looks almost like a horrific gash gasps in the neck of this pale, childlike horror.","group":"Daemon","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Aura of Doom","kind":"Su","details":"As a free action, a vulnudaemon can radiate an aura of dread and hopelessness. Any creature within 30 ft. of the vulnudaemon must succeed at a DC 18 Will save or become shaken for as long as it remains in the aura."}],"description":"These deceptive daemons personify death resulting from murder accented with betrayal. Most often formed from the souls of evil creatures killed by family or friends, vulnudaemons spread their insanity throughout the worlds by deceiving and killing all creatures they meet.\n\nVulnudaemons stalk their prey, infecting them with a sense of impending doom and watching their reactions, learning their responses before attacking and savoring their death. These daemons serve as excellent assassins, hiding in the shadows before debilitating their enemies, or striking from the protection of invisibility in order to deliver the killing blow. When facing stronger enemies, vulnudaemons seek to wear them down through a series of attacks, nicking at them and darting off, then repeating the process until their opponents bleed out.\n\nVulnudaemons often find themselves called to the Material Plane by cultists of deities associated with murder and assassination. These cultists often see vulnudaemons as sacred creatures favored by their deity, and rather than simply use the daemons as assassins, cultists often grant them a shocking degree of freedom to wander the region as they will, picking victims to fit their own agendas and murdering whomever they wish. Cultists who conjure vulnudaemons into the world usually take care to show the daemons a secret hand sign or other code that members of the cult can show them, lest the monsters decide to target one of the believers for an attack. Whether or not an accidentally targeted cultist has the time to flash her safety sign to the daemon should the creature attack her at a later date is, of course, another matter.\n\nVulnudaemons stand 3 ft. tall and weigh 25 pounds.","ecology":"","habitat_society":""},{"name":"Wayward Crusader","cr":4,"xp":1200,"race":"Human","classes":[{"class":"paladin of Iomedae","level":5}],"alignment":"LG","size":"Medium","type":"humanoid","subtypes":["human"],"init":-1,"auras":["courage (10 ft.)"],"ac":20,"ac_touch":9,"ac_flat_footed":20,"ac_mods":"+9 armor, -1 Dex, +2 shield","hp":42,"hd":"5d10+10","hdvalue":5,"fort":8,"ref":3,"will":8,"immunities":["disease","fear"],"speed":[{"type":"land","speed":20}],"melee":"mwk cold iron longsword +9 (1d8+3/19-20) or  mwk lance +9 (1d8+4/3)","ranged":"javelin +4 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel positive energy","details":"1/day, DC 15, 3d6"},{"type":"smite evil","details":"2/day, +3 attack and AC, +5 damage"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect evil"}]}],"spellsprepared_caster":"paladin","spellsprepared_caster_level":2,"spellsprepared_concentration":3,"spellsprepared":[{"spell_level":1,"spell_slots":1,"spells":[{"spell":"bless weapon"},{"spell":"lesser restoration"}]}],"strength":16,"dexterity":8,"constitution":13,"intelligence":10,"wisdom":12,"charisma":16,"baseatk":5,"cmb":8,"cmd":17,"feats":[{"feat":"Mounted Combat"},{"feat":"Ride-By Attack"},{"feat":"Skill Focus (Ride)"},{"feat":"Spirited Charge"}],"skills":[{"skill":"Diplomacy","value":11},{"skill":"Heal","value":9},{"skill":"Ride","value":4}],"languages":["Common"],"sq":[{"type":"divine bond","details":"mount"},{"type":"lay on hands","details":"2d6, 5/day"},{"type":"mercy","details":"sickened"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"Dents and nicks fail to dull the shine of this knight's armor. A sword and starburst decorate her shield.","source":"Numeria Land Of Fallen Stars","description":"Crusader 's Mount CR - Horse animal companion N Large animal Init +2; Senses low-light vision, scent; Perception +9 Defense AC 21, touch 11, flat-footed 19 (+4 armor, +2 Dex, +6 natural, -1 size) hp 37 (5d8+15) Fort +7, Ref +6, Will +4 Offense Speed 50 ft.\n\nMelee bite +6 (1d4+4), 2 hooves +4 (1d6+2) Space 10 ft.; Reach 5 ft.\n\nStatistics Str 19, Dex 14, Con 17, Int 6, Wis 12, Cha 6 Base Atk +3; CMB +8; CMD 20 (24 vs. trip) Feats Endurance, Iron Will, Multiattack Skills Perception +9 Languages Common (can't speak) SQ link, share spells Gear mwk chain shirt barding, bit and bridle, military saddle, saddlebags This crusader believed her destiny to be in Mendev, as a sword and shield against the cancer of the Worldwound.\n\nYet the long road from Taldor took her through Numeria, and here she found a cause perhaps as great, and with far fewer ready to stand with her on the side of compassion and righteousness. Now she quests to bring justice to Sovereign's Reach and mercy to the Felldales, and is always in search of stout hearts to stand beside her. She preaches the glory of the Inheritor to those in search of meaning and answers, but recognizes the universal truths behind all good faiths.\n\nPCs adventuring in Numeria may run across or even be rescued by this wayward crusader, and she doesn't hesitate to enlist them in her cause. For low-level PCs she can serve as a powerful ally and mentor, while companions who surpass her in power could even claim her crusade for their own.","ecology":"","habitat_society":"","gear":"wand of cure light wounds [9 charges], holy water [2], mwk full plate, mwk heavy steel shield, dagger, javelins [4], mwk cold iron longsword, mwk lance, everburning torch, silver holy symbol of Iomedae, spell component pouch, 83 gp"},{"name":"Werebear","cr":4,"xp":1200,"race":"Human","classes":[{"class":"ranger","level":4}],"alignment":"LG","size":"Medium","type":"humanoid","subtypes":["human","shapechanger"],"init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+4 armor, +2 Dex","hp":34,"hd":"4d10+8","hdvalue":4,"fort":5,"ref":6,"will":2,"speed":[{"type":"land","speed":30}],"melee":"mwk battleaxe +9 (1d8+4/x3)","ranged":"mwk throwing axe +7 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"orcs +2"}],"spellsprepared_caster":"ranger","spellsprepared_caster_level":1,"spellsprepared_concentration":2,"spellsprepared":[{"spell_level":1,"spell_slots":1,"spells":[{"spell":"detect poison"}]}],"strength":16,"dexterity":14,"constitution":13,"intelligence":12,"wisdom":12,"charisma":8,"baseatk":4,"cmb":7,"cmd":19,"feats":[{"feat":"Endurance"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Weapon Focus (battleaxe)"}],"skills":[{"skill":"Climb","value":8},{"skill":"Handle Animal","value":6},{"skill":"Heal","value":8},{"skill":"Knowledge (nature)","value":8},{"skill":"Perception","value":8},{"skill":"Stealth","value":7},{"skill":"Survival","value":8},{"skill":"Swim","value":8}],"languages":["Common","Sylvan"],"sq":[{"type":"change shape","details":"human, hybrid, and grizzly bear; polymorph"},{"type":"favored terrain","details":"forest +2"},{"type":"hunter's bond","details":"companions"},{"type":"lycanthropic empathy","details":"bears and dire bears"},{"type":"track","details":"+2"}],"environments":["any forests"],"organizations":["solitary","pair","family (3-6)","troupe (3-6 plus 1-4 black or grizzly bears)"],"treasure":"none","description_visual":"This humanoid is covered in shaggy fur and carries a heavy axe in one of his clawed hands.","group":"Lycanthrope","source":"PFRPG Bestiary 2","description":"In their humanoid forms, werebears tend to be muscular and broad-shouldered, with stark facial features and dark eyes. Their hair is usually red, brown, or black, and they look like they are used to a lifetime of hard work. Though by far the most benign of common lycanthropes, werebears are shunned by most normal folk, who fear and mistrust their animal transformations. Most live as recluses in forested areas or in small family units among their own kind. They avoid confrontations with strangers but don't hesitate to drive evil humanoids out of their territory.\n\nSome werebears are angry and violent, because of either temperament or a lifetime of harassment from others, and these mean ones aren't afraid to put an axe in a trespasser's face or eat someone who pushes them too far. Cool-headed werebears don't like to speak of these individuals with strangers.","ecology":"","habitat_society":"","gear":"chain shirt, masterwork battleaxe, 2 masterwork throwing axes"},{"name":"Werebear","cr":4,"xp":1200,"race":"Human","classes":[{"class":"ranger","level":4}],"alignment":"LG","size":"Large","type":"humanoid","subtypes":["human","shapechanger"],"init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":23,"ac_touch":11,"ac_flat_footed":21,"ac_mods":"+4 armor, +2 Dex, +8 natural, -1 size","hp":46,"hd":"4d10+20","hdvalue":4,"fort":6,"ref":6,"will":2,"dr":"10/silver","speed":[{"type":"land","speed":30}],"melee":"mwk battleaxe +10 (2d6+5/x3), bite +3 (1d8+2 plus curse of lycanthropy), claw +3 (1d6+2 plus grab)","ranged":"mwk throwing axe +7 (1d6+5)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"favored enemy","details":"orcs +2"}],"spellsprepared_caster":"ranger","spellsprepared_caster_level":1,"spellsprepared_concentration":5,"spellsprepared":[{"spell_level":1,"spell_slots":1,"spells":[{"spell":"detect poison"}]}],"strength":21,"dexterity":14,"constitution":19,"intelligence":12,"wisdom":12,"charisma":8,"baseatk":4,"cmb":10,"cmb_special":"+4 vs. grapple","cmd":22,"feats":[{"feat":"Endurance"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Weapon Focus (battleaxe)"}],"skills":[{"skill":"Climb","value":10},{"skill":"Handle Animal","value":6},{"skill":"Heal","value":8},{"skill":"Knowledge (nature)","value":8},{"skill":"Perception","value":8},{"skill":"Stealth","value":3},{"skill":"Survival","value":8},{"skill":"Swim","value":10}],"languages":["Common"],"sq":[{"type":"change shape","details":"human, hybrid, and bear; polymorph"},{"type":"favored terrain","details":"forest +2"},{"type":"hunter's bond","details":"companions"},{"type":"lycanthropic empathy","details":"bears and dire bears"},{"type":"track","details":"+2"}],"environments":["any forests"],"organizations":["solitary","pair","family (3-6)","troupe (3-6 plus 1-4 black or grizzly bears)"],"treasure":"none","description_visual":"This humanoid is covered in shaggy fur and carries a heavy axe in one of his clawed hands.","group":"Lycanthrope","source":"PFRPG Bestiary 2","description":"In their humanoid forms, werebears tend to be muscular and broad-shouldered, with stark facial features and dark eyes. Their hair is usually red, brown, or black, and they look like they are used to a lifetime of hard work. Though by far the most benign of common lycanthropes, werebears are shunned by most normal folk, who fear and mistrust their animal transformations. Most live as recluses in forested areas or in small family units among their own kind. They avoid confrontations with strangers but don't hesitate to drive evil humanoids out of their territory.\n\nSome werebears are angry and violent, because of either temperament or a lifetime of harassment from others, and these mean ones aren't afraid to put an axe in a trespasser's face or eat someone who pushes them too far. Cool-headed werebears don't like to speak of these individuals with strangers.","ecology":"","habitat_society":"","gear":"chain shirt, masterwork battleaxe, 2 masterwork throwing axes"},{"name":"Weretiger","cr":4,"xp":1200,"race":"Human","classes":[{"class":"rogue","level":4}],"alignment":"NE","size":"Medium","type":"humanoid","subtypes":["human","shapechanger"],"init":7,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+3 armor, +3 Dex","hp":29,"hd":"4d8+8","hdvalue":4,"fort":2,"ref":7,"will":4,"defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"mwk short sword +5 (1d6+1/19-20)","ranged":"mwk dagger +6 (1d4+1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":13,"dexterity":16,"constitution":12,"intelligence":10,"wisdom":16,"charisma":8,"baseatk":3,"cmb":4,"cmd":17,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Climb","value":7},{"skill":"Handle Animal","value":3},{"skill":"Intimidate","value":6},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":12},{"skill":"Survival","value":7},{"skill":"Swim","value":7}],"languages":["Common"],"sq":[{"type":"change shape","details":"human, hybrid, and tiger; polymorph"},{"type":"lycanthropic empathy","details":"tigers and dire tigers"},{"type":"rogue talents","details":"bleeding attack +2, fast stealth"},{"type":"trapfinding","details":"+2"}],"environments":["any plains","any swamps"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This humanoid tiger has striped fur and a muscular, lanky frame. Its feline face has sharp fangs and slitted eyes.","group":"Lycanthrope","source":"PFRPG Bestiary 2","description":"Weretigers in humanoid form have large eyes, long noses, and sharp cheekbones. Most have brown or red hair, though a few have white, black, or even blue-gray. Their movements appear careful yet casual, and a person observing one could easily assume he's watching a skilled pickpocket, graceful dancer, or sultry courtesan. Weretigers tend to be solitary creatures, only spending time with others of their kind when they feel the urge to breed. Evil weretigers enjoy the thrill of hunting intelligent prey.","ecology":"","habitat_society":"","gear":"studded leather, masterwork short sword, 2 masterwork daggers"}];
